//! Comparison with 7-Zip's PPMd var.I, `Ppmd8.c`.
//!
//! `tools/7z-oracle`, built with 7-Zip's sources by `scripts/testdata.py`,
//! encodes bytes with `Ppmd8_EncodeSymbol` (`ppmd8enc`) and decodes streams
//! with `Ppmd8_DecodeSymbol` (`ppmd8dec`), one line per request. [`answer`]
//! decodes with the port and answers as `ppmd8dec` does, so the two can be
//! compared as text.
//!
//! Two kinds of test use it:
//! - With the oracle built, streams it made of generated bytes are decoded
//!   by both, whole, stopped early, damaged, cut short, with bytes after
//!   them and with another model than they were made with.
//! - Everywhere, including where the oracle cannot be built (Windows, and
//!   the emulated i686 and s390x jobs), `testdata/oracle/ppmd8.txt` replays
//!   answers it gave earlier. `cargo test -p hivepack-zip
//!   record_ppmd8_answers -- --ignored` rewrites that file.

use std::fmt::Write as _;
use std::io::{BufRead, BufReader, Write};
use std::path::PathBuf;
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

use crate::ppmd8::{ByteIn, Ppmd8};

fn repository() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn recorded_path() -> PathBuf {
    repository().join("testdata/oracle/ppmd8.txt")
}

/// The oracle program, running.
struct Oracle {
    child: Child,
    input: ChildStdin,
    output: BufReader<ChildStdout>,
}

impl Oracle {
    /// The oracle built by `scripts/testdata.py`, or `None` with a note when
    /// it has not been built. CI lists the `generated` group in
    /// `HIVEPACK_TESTDATA_REQUIRED` where it builds the oracle, and then a
    /// missing oracle fails the test.
    fn spawn() -> Option<Oracle> {
        let cache = std::env::var_os("HIVEPACK_TESTDATA")
            .map(PathBuf::from)
            .unwrap_or_else(|| repository().join("target/testdata"));
        let folder = cache.join("7z-oracle");
        if !folder.join(".complete").exists() {
            let required = std::env::var("HIVEPACK_TESTDATA_REQUIRED").unwrap_or_default();
            assert!(
                !required.split(',').any(|g| g == "all" || g == "generated"),
                "the oracle is missing: run `python3 scripts/testdata.py fetch --group generated`"
            );
            eprintln!(
                "skipping: the oracle is not built (scripts/testdata.py fetch --group generated)"
            );
            return None;
        }
        let mut child = Command::new(folder.join("oracle"))
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .spawn()
            .expect("the oracle starts");
        let input = child.stdin.take().expect("stdin");
        let output = BufReader::new(child.stdout.take().expect("stdout"));
        Some(Oracle {
            child,
            input,
            output,
        })
    }

    fn ask(&mut self, request: &str) -> String {
        writeln!(self.input, "{request}").expect("request sent");
        self.input.flush().expect("request sent");
        let mut line = String::new();
        self.output.read_line(&mut line).expect("answer read");
        let line = line.trim_end().to_string();
        assert!(
            line != "bad" && !line.is_empty(),
            "the oracle answered {line:?} to {request:.200}"
        );
        line
    }
}

impl Drop for Oracle {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn hex(bytes: &[u8]) -> String {
    if bytes.is_empty() {
        return "-".into();
    }
    let mut text = String::with_capacity(2 * bytes.len());
    for byte in bytes {
        let _ = write!(text, "{byte:02x}");
    }
    text
}

fn unhex(text: &str) -> Vec<u8> {
    if text == "-" {
        return Vec::new();
    }
    (0..text.len() / 2)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).expect("hex"))
        .collect()
}

/// The stream, read as the oracle's `byte_in_read` reads it.
struct SliceIn<'a> {
    buf: &'a [u8],
    pos: usize,
    extra: bool,
}

impl ByteIn for SliceIn<'_> {
    fn read_byte(&mut self) -> u8 {
        match self.buf.get(self.pos) {
            Some(&b) => {
                self.pos += 1;
                b
            }
            None => {
                self.extra = true;
                0
            }
        }
    }
}

/// The port's answer to a `ppmd8dec` request, in the oracle's format.
fn answer(request: &str) -> String {
    let fields: Vec<&str> = request.split(' ').collect();
    let ["ppmd8dec", order, mem, restore, max, data] = fields[..] else {
        panic!("not a ppmd8dec request: {request:.200}");
    };
    let order: u32 = order.parse().expect("order");
    let mem: u32 = mem.parse().expect("memory");
    let restore: u32 = restore.parse().expect("restore method");
    let max: usize = max.parse().expect("most symbols");
    let data = unhex(data);
    let Some(mut ppmd) = Ppmd8::new(mem) else {
        return "mem".into();
    };
    let mut input = SliceIn {
        buf: &data,
        pos: 0,
        extra: false,
    };
    let init = ppmd.init_range_dec(&mut input);
    ppmd.init(order, restore);
    let mut out = Vec::new();
    let mut sym = 256;
    while out.len() < max {
        sym = ppmd.decode_symbol(&mut input);
        if sym < 0 {
            break;
        }
        out.push(sym as u8);
        sym = 256;
    }
    format!(
        "{} {sym} {} {} {} {}",
        u8::from(init),
        u8::from(input.extra),
        u8::from(ppmd.range_dec_is_finished_ok()),
        input.pos,
        hex(&out)
    )
}

/// An answer as the replay file keeps it: the bytes decoded as their count
/// and FNV-1a hash, so that the file stays small.
fn recorded_form(answer: &str) -> String {
    match answer.rsplit_once(' ') {
        Some((head, out)) => {
            let out = unhex(out);
            let mut hash: u64 = 0xCBF2_9CE4_8422_2325;
            for &b in &out {
                hash = (hash ^ u64::from(b)).wrapping_mul(0x0100_0000_01B3);
            }
            format!("{head} {}:{hash:016x}", out.len())
        }
        None => answer.into(),
    }
}

struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9E37_79B9_7F4A_7C15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^ (z >> 31)
    }

    /// A number in `low..=high`.
    fn range(&mut self, low: u64, high: u64) -> u64 {
        low + self.next() % (high - low + 1)
    }

    fn below(&mut self, n: usize) -> usize {
        (self.next() % n as u64) as usize
    }
}

const WORDS: [&str; 24] = [
    "the", "of", "archive", "entry", "and", "PPMd", "model", "context", "a", "to", "is", "data",
    "symbol", "order", "in", "memory", "\n", "zip", ", ", "range", "coder", "it", "byte", ". ",
];

/// `len` bytes of one of several kinds, each wearing the model differently:
/// text, noise (which fills the memory quickest), runs (binary contexts),
/// records of a few fields, and a mix.
fn input(rng: &mut Rng, len: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(len);
    match rng.below(6) {
        0 => {
            while out.len() < len {
                out.extend_from_slice(WORDS[rng.below(WORDS.len())].as_bytes());
                out.push(b' ');
            }
        }
        1 => out.extend((0..len).map(|_| rng.next() as u8)),
        2 => {
            while out.len() < len {
                let b = rng.next() as u8 % 4;
                let run = rng.range(1, 300) as usize;
                out.extend(std::iter::repeat_n(b, run));
            }
        }
        3 => {
            let mut counter = rng.next() as u32;
            while out.len() < len {
                counter = counter.wrapping_add(rng.range(1, 3) as u32);
                out.extend_from_slice(&counter.to_le_bytes());
                out.extend_from_slice(b"rec:");
                out.push(rng.next() as u8 % 16);
            }
        }
        4 => {
            // A small alphabet, so each context sees few symbols.
            let alphabet = rng.range(2, 12);
            out.extend((0..len).map(|_| b'a' + (rng.next() % alphabet) as u8));
        }
        _ => {
            while out.len() < len {
                if rng.below(3) == 0 {
                    let n = rng.range(1, 64) as usize;
                    out.extend((0..n).map(|_| rng.next() as u8));
                } else {
                    out.extend_from_slice(WORDS[rng.below(WORDS.len())].as_bytes());
                }
            }
        }
    }
    out.truncate(len);
    out
}

/// The memory sizes models are made with: small ones run out, and are
/// restarted or cut off, within a few kilobytes of noise; ZIP's own are
/// whole MiB.
const MEMORY: [u32; 6] = [1 << 12, 1 << 14, 1 << 16, 1 << 18, 1 << 20, 3 << 20];

/// `ppmd8dec` requests: streams the oracle made, then changed.
fn requests(oracle: &mut Oracle, rng: &mut Rng, count: usize, largest: usize) -> Vec<String> {
    let mut requests = Vec::new();
    for case in 0..count {
        let order = match case % 5 {
            0 => 2,
            1 => 16,
            _ => rng.range(2, 16) as u32,
        };
        let mem = MEMORY[rng.below(MEMORY.len())];
        let restore = (case / 2 % 2) as u32;
        let len = match rng.below(4) {
            0 => rng.below(16),
            1 => rng.below(1000),
            _ => rng.below(largest + 1),
        };
        let data = input(rng, len);
        let reply = oracle.ask(&format!("ppmd8enc {order} {mem} {restore} {}", hex(&data)));
        let stream = unhex(&reply);
        let request = |order: u32, mem: u32, restore: u32, max: usize, stream: &[u8]| {
            format!("ppmd8dec {order} {mem} {restore} {max} {}", hex(stream))
        };
        // Whole, and stopped early.
        requests.push(request(order, mem, restore, len + 8, &stream));
        requests.push(request(order, mem, restore, rng.below(len + 1), &stream));
        // Garbage may decode for ever: past its end the stream reads as 0.
        let max = 2 * len + 64;
        // Damaged.
        let mut damaged = stream.clone();
        for _ in 0..rng.range(1, 3) {
            let at = match rng.below(3) {
                0 => rng.below(damaged.len().min(6)),
                _ => rng.below(damaged.len()),
            };
            damaged[at] ^= 1 << rng.below(8);
        }
        requests.push(request(order, mem, restore, max, &damaged));
        // Cut short, and with bytes after it.
        let cut = rng.below(stream.len());
        requests.push(request(order, mem, restore, max, &stream[..cut]));
        let mut longer = stream.clone();
        longer.extend((0..rng.range(1, 9)).map(|_| rng.next() as u8));
        requests.push(request(order, mem, restore, max, &longer));
        // With another model.
        let other_order = rng.range(2, 16) as u32;
        let other_mem = MEMORY[rng.below(MEMORY.len())];
        requests.push(request(other_order, other_mem, 1 - restore, max, &stream));
        if case % 8 == 0 {
            // Noise, and a stream the range decoder rejects at once.
            let noise: Vec<u8> = (0..rng.below(400)).map(|_| rng.next() as u8).collect();
            requests.push(request(order, mem, restore, 1000, &noise));
            let mut high = vec![0xFF; 4];
            high.extend_from_slice(&stream);
            requests.push(request(order, mem, restore, max, &high));
        }
    }
    requests
}

#[test]
fn port_decodes_like_7zip() {
    let Some(mut oracle) = Oracle::spawn() else {
        return;
    };
    let mut rng = Rng(0x5EED_0098);
    let mut checked = 0;
    for request in requests(&mut oracle, &mut rng, 160, 60_000) {
        let want = oracle.ask(&request);
        assert_eq!(answer(&request), want, "{request:.300}");
        checked += 1;
    }
    assert!(checked >= 1000, "only {checked} requests");
}

#[test]
fn port_matches_recorded_answers() {
    let text = std::fs::read_to_string(recorded_path()).expect("testdata/oracle/ppmd8.txt");
    let mut checked = 0;
    for line in text
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
    {
        let (request, want) = line.split_once('\t').expect("request, tab, answer");
        assert_eq!(recorded_form(&answer(request)), want, "{request:.300}");
        checked += 1;
    }
    assert!(checked > 500, "only {checked} recorded answers");
}

#[test]
#[ignore = "rewrites testdata/oracle/ppmd8.txt from the oracle"]
fn record_ppmd8_answers() {
    let mut oracle = Oracle::spawn().expect("the oracle is built");
    let mut rng = Rng(0x5EED_0099);
    let mut text = String::from(
        "# Answers from 7-Zip 26.05's Ppmd8.c (tools/7z-oracle), replayed by crates/zip/src/ppmd8_oracle.rs.\n\
         # Regenerate with: cargo test -p hivepack-zip record_ppmd8_answers -- --ignored\n",
    );
    for request in requests(&mut oracle, &mut rng, 100, 3000) {
        let reply = oracle.ask(&request);
        let _ = writeln!(text, "{request}\t{}", recorded_form(&reply));
    }
    std::fs::write(recorded_path(), text).expect("written");
}
